/* Bit-for-bit intent check against the Python reference.
 *
 * The golden vectors are generated by tools/make_goldens.py from
 * src/stemenvelope/envelope.py, so a divergence here means the C port drifted
 * from the documented behaviour — not that the vector is wrong.
 *
 * Build & run:  make -C variants/s3 check
 */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>

#include "golden.h"
#include "stemenvelope_s3.h"

#define TOL 2e-4f

int main(void)
{
    static float gains[GOLD_N_STEMS * GOLD_N_BANDS];
    se_envelope_t env;
    int step;

    if (se_init(&env, GOLD_N_STEMS, GOLD_N_BANDS, gains) != SE_OK) {
        fprintf(stderr, "se_init failed\n");
        return 2;
    }
    /* mirror the parameters used when the golden vectors were produced */
    env.tau_rise_s = 0.2f;
    env.tau_fall_s = 0.4f;
    env.presence_window_db = 18.0f;
    env.silence_floor_db = -60.0f;
    env.max_boost_db = 3.0f;
    env.max_cut_db = -9.0f;

    const float *inputs[GOLD_STEPS] = {
        GOLD_IN_0, GOLD_IN_1, GOLD_IN_2, GOLD_IN_3, GOLD_IN_4, GOLD_IN_5,
        GOLD_IN_6, GOLD_IN_7, GOLD_IN_8, GOLD_IN_9, GOLD_IN_10, GOLD_IN_11
    };
    const float *curves[GOLD_STEPS] = {
        GOLD_CURVE_0, GOLD_CURVE_1, GOLD_CURVE_2, GOLD_CURVE_3, GOLD_CURVE_4, GOLD_CURVE_5,
        GOLD_CURVE_6, GOLD_CURVE_7, GOLD_CURVE_8, GOLD_CURVE_9, GOLD_CURVE_10, GOLD_CURVE_11
    };
    const float *expected[GOLD_STEPS] = {
        GOLD_OUT_0, GOLD_OUT_1, GOLD_OUT_2, GOLD_OUT_3, GOLD_OUT_4, GOLD_OUT_5,
        GOLD_OUT_6, GOLD_OUT_7, GOLD_OUT_8, GOLD_OUT_9, GOLD_OUT_10, GOLD_OUT_11
    };
    const int actives[GOLD_STEPS] = {
        GOLD_ACTIVE_0, GOLD_ACTIVE_1, GOLD_ACTIVE_2, GOLD_ACTIVE_3, GOLD_ACTIVE_4, GOLD_ACTIVE_5,
        GOLD_ACTIVE_6, GOLD_ACTIVE_7, GOLD_ACTIVE_8, GOLD_ACTIVE_9, GOLD_ACTIVE_10, GOLD_ACTIVE_11
    };

    for (step = 0; step < GOLD_STEPS; ++step) {
        float dt = (step == 0) ? GOLD_DT_0 : 0.058f;
        float worst = 0.0f;
        int i;
        if (se_step(&env, inputs[step], curves[step], dt, actives[step]) != SE_OK) {
            fprintf(stderr, "se_step failed at step %d\n", step);
            return 2;
        }
        for (i = 0; i < GOLD_N_STEMS * GOLD_N_BANDS; ++i) {
            float err = fabsf(gains[i] - expected[step][i]);
            if (err > worst) worst = err;
        }
        if (worst > TOL) {
            fprintf(stderr, "step %d: max |C - python| = %.6f > %.6f\n", step, (double)worst,
                    (double)TOL);
            return 1;
        }
        if (step == GOLD_STEPS - 1) {
            printf("c/python parity: %d steps, worst error %.6f dB (tol %.6f)\n",
                   GOLD_STEPS, (double)worst, (double)TOL);
        }
    }

    /* fail-open contract: an inactive tick must decay toward 0 dB, and the
     * envelope must never leave its bounds even with absurd input */
    env.max_boost_db = 3.0f;
    env.max_cut_db = -9.0f;
    {
        float insanely_loud[GOLD_N_STEMS * GOLD_N_BANDS];
        float insane_curve[GOLD_N_BANDS];
        int i;
        for (i = 0; i < GOLD_N_STEMS * GOLD_N_BANDS; ++i) insanely_loud[i] = 1e9f;
        for (i = 0; i < GOLD_N_BANDS; ++i) insane_curve[i] = 1e9f;
        if (se_step(&env, insanely_loud, insane_curve, 10.0f, 1) != SE_OK) return 2;
        for (i = 0; i < GOLD_N_STEMS * GOLD_N_BANDS; ++i) {
            if (gains[i] > 3.0f + 1e-3f || gains[i] < -9.0f - 1e-3f) {
                fprintf(stderr, "bound violated: %.4f\n", (double)gains[i]);
                return 1;
            }
        }
    }
    printf("bounds ok\n");

    if (se_step(NULL, inputs[0], curves[0], 0.05f, 1) != SE_ERR_ARG) {
        fprintf(stderr, "expected SE_ERR_ARG for NULL env\n");
        return 1;
    }
    printf("arg checks ok\n");
    return 0;
}
